package com.tutortimer;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;

@ConfigGroup("tutortimer")
public interface TutorTimerConfig extends Config
{
    @ConfigItem(
        keyName = "showInfoBox",
        name = "Show info box",
        description = "Toggle visibility of the info box timer",
        position = 0
    )
    default boolean showInfoBox()
    {
        return true;
    }

    @ConfigItem(
        keyName = "showWhenReady",
        name = "Show info box only when ready",
        description = "Show the info box only when the timer is ready; disable to show it at all times",
        position = 1
    )
    default boolean showWhenReady()
    {
        return false;
    }

    @ConfigItem(
        keyName = "notifyOnReady",
        name = "Notify when ready",
        description = "Send a notification when the cooldown expires",
        position = 2
    )
    default boolean notifyOnReady()
    {
        return false;
    }

    @ConfigItem(
        keyName = "showSeconds",
        name = "Show seconds",
        description = "Show seconds in the countdown, or just minutes",
        position = 3
    )
    default boolean showSeconds()
    {
        return true;
    }
}

package com.tutortimer;

import net.runelite.client.ui.overlay.infobox.InfoBox;
import javax.annotation.Nonnull;

import java.awt.*;
import java.awt.image.BufferedImage;

public class TutorTimerInfoBox extends InfoBox
{
    private final TutorTimerPlugin plugin;

    public TutorTimerInfoBox(BufferedImage image, @Nonnull TutorTimerPlugin plugin)
    {
        super(image, plugin);
        this.plugin = plugin;
    }

    @Override
    public String getTooltip()
    {
        return plugin.getTooltipText();
    }

    @Override
    public String getText()
    {
        return plugin.getTimerText();
    }

    @Override
    public Color getTextColor()
    {
        if (plugin.isReady()) return Color.GREEN;
        if (plugin.isUnknown()) return Color.YELLOW;
        return Color.WHITE;
    }
}

package com.tutortimer;

import net.runelite.api.ChatMessageType;
import net.runelite.api.events.ChatMessage;
import net.runelite.api.events.GameTick;
import net.runelite.client.Notifier;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.game.ItemManager;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.overlay.infobox.InfoBoxManager;

import javax.inject.Inject;
import java.awt.image.BufferedImage;
import java.time.Duration;
import java.time.Instant;

import lombok.extern.slf4j.Slf4j;

import com.google.inject.Provides;

@Slf4j
@PluginDescriptor(
    name = "Tutor Timer",
    description = "Tracks the 30-minute cooldown for claiming free runes and training arrows from the Lumbridge combat tutors.",
    tags = {"magic", "ranged", "tutor", "runes", "arrows", "timer", "cooldown", "combat", "free", "lumbridge"}
)
public class TutorTimerPlugin extends Plugin
{
    static final Duration COOLDOWN = Duration.ofMinutes(30);
    private static final String CONFIG_GROUP = "tutortimer";
    private static final String LAST_CLAIM_KEY = "lastClaim";
    private static final String LAST_KNOWN_COOLDOWN_KEY = "lastKnownCooldown";
    private static final String LAST_SHUTDOWN_KEY = "lastShutdown";

    private static final String MIKASI_GIVES = "Mikasi gives you";
    private static final String NEMARTI_GIVES = "Nemarti gives you";
    private static final String COOLDOWN_REJECT = "every half an hour";

    private static final long KNOWN_COOLDOWN_CHECK_INTERVAL_MS = 60_000L;

    @Provides
    TutorTimerConfig provideConfig(ConfigManager configManager)
    {
        return configManager.getConfig(TutorTimerConfig.class);
    }

    @Inject private ConfigManager configManager;
    @Inject private InfoBoxManager infoBoxManager;
    @Inject private ItemManager itemManager;
    @Inject private Notifier notifier;
    @Inject private TutorTimerConfig config;

    // use Optionals rather than nullable fields; avoids any risk of NPEs
    private java.util.Optional<Instant> lastClaimTime = java.util.Optional.empty();
    private java.util.Optional<Instant> lastKnownCooldownTime = java.util.Optional.empty();
    private boolean knownOnCooldown;
    private boolean notifiedReady;
    private TutorTimerInfoBox infoBox;
    private long lastKnownCooldownExpiryCheck;

    @Override
    protected void startUp()
    {
        try
        {
            loadLastClaimTime();
            addInfoBox();
        }
        catch (Exception ex)
        {
            log.error("Tutor Timer startup failed", ex);
        }
    }

    @Override
    protected void shutDown()
    {
        try
        {
            configManager.setConfiguration(CONFIG_GROUP, LAST_SHUTDOWN_KEY,
                String.valueOf(System.currentTimeMillis()));
            removeInfoBox();
        }
        catch (Exception ex)
        {
            log.error("Tutor Timer shutdown failed", ex);
        }
    }


    // Load persisted state from config. Package-private for tests.
    void loadLastClaimTime()
    {
        if (configManager == null) return;

        loadLastClaimTimeFromConfig();
        loadLastKnownCooldownFromConfig();
        detectStaleClaim();
        if (configManager != null)
        {
            configManager.unsetConfiguration(CONFIG_GROUP, LAST_SHUTDOWN_KEY);
        }
    }

    private void loadLastClaimTimeFromConfig()
    {
        String saved = configManager.getConfiguration(CONFIG_GROUP, LAST_CLAIM_KEY);
        if (saved != null)
        {
            try { lastClaimTime = java.util.Optional.of(Instant.ofEpochMilli(Long.parseLong(saved))); }
            catch (NumberFormatException e) { lastClaimTime = java.util.Optional.empty(); }
        }
    }

    private void loadLastKnownCooldownFromConfig()
    {
        String savedKnown = configManager.getConfiguration(CONFIG_GROUP, LAST_KNOWN_COOLDOWN_KEY);
        if (savedKnown != null)
        {
            try
            {
                lastKnownCooldownTime = java.util.Optional.of(Instant.ofEpochMilli(Long.parseLong(savedKnown)));
                if (lastClaimTime.isEmpty() && isKnownCooldownActive())
                {
                    knownOnCooldown = true;
                }
                else if (!isKnownCooldownActive())
                {
                    lastKnownCooldownTime = java.util.Optional.empty();
                    if (configManager != null)
                    {
                        configManager.unsetConfiguration(CONFIG_GROUP, LAST_KNOWN_COOLDOWN_KEY);
                    }
                }
            }
            catch (NumberFormatException e) { lastKnownCooldownTime = java.util.Optional.empty(); }
        }
    }

    private void detectStaleClaim()
    {
        String savedShutdown = configManager.getConfiguration(CONFIG_GROUP, LAST_SHUTDOWN_KEY);
        if (savedShutdown != null && lastClaimTime.isPresent())
        {
            try
            {
                Instant shutdown = Instant.ofEpochMilli(Long.parseLong(savedShutdown));
                Instant expire = lastClaimTime.get().plus(COOLDOWN);
                if (shutdown.isAfter(lastClaimTime.get()) && shutdown.isBefore(expire))
                {
                    lastClaimTime = java.util.Optional.empty();
                    knownOnCooldown = false;
                    lastKnownCooldownTime = java.util.Optional.empty();
                    if (configManager != null)
                    {
                        configManager.unsetConfiguration(CONFIG_GROUP, LAST_CLAIM_KEY);
                        configManager.unsetConfiguration(CONFIG_GROUP, LAST_KNOWN_COOLDOWN_KEY);
                    }
                }
            }
            catch (NumberFormatException e)
            {
                log.warn(
                    "Malformed timestamp '{}' for key '{}' in config group '{}' while detecting stale claim. "
                        + "The malformed value will be ignored and the plugin will fall back to normal behavior; "
                        + "you may need to clear the Tutor Timer plugin configuration if this warning persists.",
                    savedShutdown, LAST_SHUTDOWN_KEY, CONFIG_GROUP, e
                );
            }
        }
    }

    private void saveLastClaimTime()
    {
        if (lastClaimTime.isPresent())
        {
            configManager.setConfiguration(CONFIG_GROUP, LAST_CLAIM_KEY,
                String.valueOf(lastClaimTime.get().toEpochMilli()));
        }
    }

    private void addInfoBox()
    {
        try
        {
            removeInfoBox();
            BufferedImage icon = itemManager.getImage(558);
            infoBox = new TutorTimerInfoBox(icon, this);
            infoBoxManager.addInfoBox(infoBox);
        }
        catch (Exception ex)
        {
            log.error("Unable to create info box", ex);
        }
    }

    private void removeInfoBox()
    {
        if (infoBox != null)
        {
            infoBoxManager.removeInfoBox(infoBox);
            infoBox = null;
        }
    }

    // --- Event handlers ---

    @Subscribe
    public void onChatMessage(ChatMessage event)
    {
        ChatMessageType type = event.getType();
        if (type != ChatMessageType.DIALOG
            && type != ChatMessageType.GAMEMESSAGE

            && type != ChatMessageType.MESBOX) return;

        String msg = event.getMessage();

        if (msg.contains(MIKASI_GIVES) || msg.contains(NEMARTI_GIVES))
        {
            handleTutorClaim();
        }
        else if (msg.contains("I work with the Ranged Combat tutor")
              || msg.contains("I work with the Magic tutor"))
        {
            handleTutorIntro();
        }
        else if (msg.contains(COOLDOWN_REJECT))
        {
            handleCooldownRejection();
        }
    }

    private void handleTutorClaim()
    {
        lastClaimTime = java.util.Optional.of(Instant.now());
        knownOnCooldown = true;
        notifiedReady = false;
        saveLastClaimTime();
        lastKnownCooldownTime = java.util.Optional.empty();
        if (configManager != null)
        {
            configManager.unsetConfiguration(CONFIG_GROUP, LAST_KNOWN_COOLDOWN_KEY);
        }
    }

    private void handleTutorIntro()
    {
        clearStaleClaim();
        if (lastClaimTime.isEmpty())
        {
            lastKnownCooldownTime = java.util.Optional.of(Instant.now());
            knownOnCooldown = true;
            configManager.setConfiguration(CONFIG_GROUP, LAST_KNOWN_COOLDOWN_KEY,
                String.valueOf(lastKnownCooldownTime.get().toEpochMilli()));
        }
    }

    private void handleCooldownRejection()
    {
        clearStaleClaim();
        lastKnownCooldownTime = java.util.Optional.of(Instant.now());
        knownOnCooldown = true;
        configManager.setConfiguration(CONFIG_GROUP, LAST_KNOWN_COOLDOWN_KEY,
            String.valueOf(lastKnownCooldownTime.get().toEpochMilli()));
    }

    // If the previous claim has expired, clear it so new tracking can start.
    private void clearStaleClaim()
    {
        if (lastClaimTime.isPresent() && isReady())
        {
            lastClaimTime = java.util.Optional.empty();
            knownOnCooldown = false;
            lastKnownCooldownTime = java.util.Optional.empty();
            if (configManager != null)
            {
                configManager.unsetConfiguration(CONFIG_GROUP, LAST_CLAIM_KEY);
                configManager.unsetConfiguration(CONFIG_GROUP, LAST_KNOWN_COOLDOWN_KEY);
            }
        }
    }

    @Subscribe
    public void onGameTick(GameTick event)
    {
        if (config.notifyOnReady() && !notifiedReady && isReady())
        {
            notifier.notify("Your free runes or arrows are ready to claim!");
            notifiedReady = true;
        }

        boolean shouldShow = config.showInfoBox() && (!config.showWhenReady() || isReady());
        if (!shouldShow) removeInfoBox();
        else if (infoBox == null) addInfoBox();

        // Throttled: clear persisted known-cooldown when it expires
        long now = System.currentTimeMillis();
        if (now - lastKnownCooldownExpiryCheck >= KNOWN_COOLDOWN_CHECK_INTERVAL_MS)
        {
            lastKnownCooldownExpiryCheck = now;
            if (lastClaimTime.isEmpty() && lastKnownCooldownTime.isPresent() && !isKnownCooldownActive())
            {
                lastKnownCooldownTime = java.util.Optional.empty();
                knownOnCooldown = false;
                if (configManager != null)
                {
                    configManager.unsetConfiguration(CONFIG_GROUP, LAST_KNOWN_COOLDOWN_KEY);
                }
            }
        }
    }

    @Subscribe
    public void onConfigChanged(ConfigChanged event)
    {
        if (CONFIG_GROUP.equals(event.getGroup()))
        {
            removeInfoBox();
        }
    }

    // --- InfoBox API ---

    public String getTooltipText()
    {
        if (lastClaimTime.isEmpty() && !knownOnCooldown)
            return "Tutor Timer - claim runes or arrows to start tracking";
        if (lastClaimTime.isEmpty())
            return "Tutor Timer - on cooldown, but unknown time remaining";
        if (isReady())
            return "Tutor Timer - ready to claim!";
        return "Tutor Timer - " + getTimerText() + " remaining";
    }

    public String getTimerText()
    {
        if (lastClaimTime.isEmpty())
            return knownOnCooldown ? "< 30m" : "?";

        Duration elapsed = Duration.between(lastClaimTime.get(), Instant.now());
        Duration remaining = COOLDOWN.minus(elapsed);
        if (remaining.isNegative() || remaining.isZero()) return "Ready!";

        long minutes = remaining.toMinutes();
        long seconds = remaining.getSeconds() % 60;
        return config.showSeconds()
            ? String.format("%d:%02d", minutes, seconds)
            : String.format("%dm", minutes);
    }

    public boolean isReady()
    {
        return lastClaimTime.isPresent()
            && Duration.between(lastClaimTime.get(), Instant.now()).compareTo(COOLDOWN) >= 0;
    }

    public boolean isUnknown()
    {
        return lastClaimTime.isEmpty();
    }

    private boolean isKnownCooldownActive()
    {
        return lastKnownCooldownTime
            .map(t -> Instant.now().isBefore(t.plus(COOLDOWN)))
            .orElse(false);
    }
}

package com.tutortimer;

import net.runelite.client.RuneLite;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.externalplugins.ExternalPluginManager;
import net.runelite.client.plugins.Plugin;
import net.runelite.api.ChatMessageType;
import net.runelite.api.events.ChatMessage;
import org.junit.Test;

import java.lang.reflect.Field;
import java.time.Duration;
import java.time.Instant;

import static org.junit.Assert.*;
import static org.mockito.Mockito.*;

public class TutorTimerPluginTest
{
    @SuppressWarnings("unchecked")
    public static void main(String[] args) throws Exception
    {
        ExternalPluginManager.loadBuiltin(TutorTimerPlugin.class);
        RuneLite.main(args);
    }

    // --- Reflection helpers ---

    private static void setField(Object obj, String name, Object value) throws Exception
    {
        Field f = obj.getClass().getDeclaredField(name);
        f.setAccessible(true);
        f.set(obj, value);
    }

    private static Object getField(Object obj, String name) throws Exception
    {
        Field f = obj.getClass().getDeclaredField(name);
        f.setAccessible(true);
        return f.get(obj);
    }

    // --- Basic sanity ---

    @Test
    public void pluginClassIsPresent()
    {
        assertNotNull(TutorTimerPlugin.class);
    }

    @Test
    public void pluginImplementsRuneLitePlugin()
    {
        assertTrue(Plugin.class.isAssignableFrom(TutorTimerPlugin.class));
    }

    // --- Display logic (InfoBox public API) ---

    @Test
    public void getTimerText_unknownAndKnownOnCooldown() throws Exception
    {
        TutorTimerPlugin plugin = new TutorTimerPlugin();
        assertEquals("?", plugin.getTimerText());

        setField(plugin, "knownOnCooldown", true);
        assertEquals("< 30m", plugin.getTimerText());
    }

    @Test
    public void isReady_logic() throws Exception
    {
        TutorTimerPlugin plugin = new TutorTimerPlugin();
        assertFalse(plugin.isReady());

        setField(plugin, "lastClaimTime", java.util.Optional.of(Instant.now().minus(TutorTimerPlugin.COOLDOWN).minusSeconds(1)));
        assertTrue(plugin.isReady());

        setField(plugin, "lastClaimTime", java.util.Optional.of(Instant.now()));
        assertFalse(plugin.isReady());
    }

    @Test
    public void getTimerText_showsSecondsWhenConfigured() throws Exception
    {
        TutorTimerPlugin plugin = new TutorTimerPlugin();
        setField(plugin, "config", new TutorTimerConfig()
        {
            @Override
            public boolean showSeconds()
            {
                return true;
            }
        });
        setField(plugin, "lastClaimTime", java.util.Optional.of(Instant.now().minus(Duration.ofMinutes(29)).minusSeconds(30)));
        assertTrue(plugin.getTimerText().matches("\\d+:\\d{2}"));
    }

    @Test
    public void getTooltipText_variousStates() throws Exception
    {
        TutorTimerPlugin plugin = new TutorTimerPlugin();
        setField(plugin, "config", new TutorTimerConfig() { });

        assertEquals("Tutor Timer - claim runes or arrows to start tracking", plugin.getTooltipText());

        setField(plugin, "knownOnCooldown", true);
        assertEquals("Tutor Timer - on cooldown, but unknown time remaining", plugin.getTooltipText());

        setField(plugin, "lastClaimTime", java.util.Optional.of(Instant.now().minus(TutorTimerPlugin.COOLDOWN).minusSeconds(1)));
        assertEquals("Tutor Timer - ready to claim!", plugin.getTooltipText());

        setField(plugin, "lastClaimTime", java.util.Optional.of(Instant.now().minus(Duration.ofMinutes(29)).minusSeconds(30)));
        String tooltip = plugin.getTooltipText();
        assertTrue(tooltip.startsWith("Tutor Timer - "));
        assertTrue(tooltip.endsWith(" remaining"));
    }

    // --- Chat message handling ---

    @Test
    public void onChatMessage_detectsMesboxClaim() throws Exception
    {
        TutorTimerPlugin plugin = new TutorTimerPlugin();
        setField(plugin, "configManager", mock(ConfigManager.class));

        ChatMessage ev = mock(ChatMessage.class);
        when(ev.getType()).thenReturn(ChatMessageType.MESBOX);
        when(ev.getMessage()).thenReturn("Mikasi gives you 30 mind runes and 30 air runes.");

        plugin.onChatMessage(ev);

        assertTrue((boolean) getField(plugin, "knownOnCooldown"));
        assertTrue(((java.util.Optional<?>) getField(plugin, "lastClaimTime")).isPresent());
    }

    @Test
    public void onChatMessage_introSetsKnownCooldown() throws Exception
    {
        TutorTimerPlugin plugin = new TutorTimerPlugin();
        ConfigManager cfg = mock(ConfigManager.class);
        setField(plugin, "configManager", cfg);

        ChatMessage ev = mock(ChatMessage.class);
        when(ev.getType()).thenReturn(ChatMessageType.DIALOG);
        when(ev.getMessage()).thenReturn(
            "Ranged combat tutor|I work with the Magic tutor to give out consumable items.");

        plugin.onChatMessage(ev);

        assertNotNull(getField(plugin, "lastKnownCooldownTime"));
        verify(cfg).setConfiguration(eq("tutortimer"), eq("lastKnownCooldown"), anyString());
    }

    @Test
    public void onChatMessage_cooldownRejectionClearsStaleClaim() throws Exception
    {
        TutorTimerPlugin plugin = new TutorTimerPlugin();
        ConfigManager cfg = mock(ConfigManager.class);
        when(cfg.getConfiguration("tutortimer", "lastClaim")).thenReturn("existing");
        setField(plugin, "configManager", cfg);
        setField(plugin, "lastClaimTime", java.util.Optional.of(Instant.now().minus(TutorTimerPlugin.COOLDOWN).minusSeconds(1)));

        ChatMessage ev = mock(ChatMessage.class);
        when(ev.getType()).thenReturn(ChatMessageType.GAMEMESSAGE);
        when(ev.getMessage()).thenReturn("You can only get items every half an hour.");

        plugin.onChatMessage(ev);

        Object val1 = getField(plugin, "lastClaimTime");
        assertFalse(((java.util.Optional<?>) val1).isPresent());
        assertTrue((boolean) getField(plugin, "knownOnCooldown"));
    }

    @Test
    public void onChatMessage_tutorIntroClearsStaleClaim() throws Exception
    {
        TutorTimerPlugin plugin = new TutorTimerPlugin();
        ConfigManager cfg = mock(ConfigManager.class);
        when(cfg.getConfiguration("tutortimer", "lastClaim")).thenReturn("existing");
        setField(plugin, "configManager", cfg);
        setField(plugin, "lastClaimTime", java.util.Optional.of(Instant.now().minus(TutorTimerPlugin.COOLDOWN).minusSeconds(1)));

        ChatMessage ev = mock(ChatMessage.class);
        when(ev.getType()).thenReturn(ChatMessageType.DIALOG);
        when(ev.getMessage()).thenReturn("I work with the Magic tutor to give out items.");

        plugin.onChatMessage(ev);

        Object val2 = getField(plugin, "lastClaimTime");
        assertFalse(((java.util.Optional<?>) val2).isPresent());
        assertTrue((boolean) getField(plugin, "knownOnCooldown"));
    }

    // --- Config persistence ---

    @Test
    public void loadLastClaimTime_readsSavedValue() throws Exception
    {
        TutorTimerPlugin plugin = new TutorTimerPlugin();
        long epoch = Instant.now().minus(Duration.ofMinutes(10)).toEpochMilli();

        ConfigManager cfg = mock(ConfigManager.class);
        when(cfg.getConfiguration("tutortimer", "lastClaim")).thenReturn(String.valueOf(epoch));
        when(cfg.getConfiguration("tutortimer", "lastKnownCooldown")).thenReturn(null);
        when(cfg.getConfiguration("tutortimer", "lastShutdown")).thenReturn(null);
        setField(plugin, "configManager", cfg);

        plugin.loadLastClaimTime();

        Object val = getField(plugin, "lastClaimTime");
        assertEquals(Instant.ofEpochMilli(epoch), ((java.util.Optional<?>) val).get());
    }

    @Test
    public void loadLastClaimTime_knownCooldownPersisted() throws Exception
    {
        TutorTimerPlugin plugin = new TutorTimerPlugin();
        long epoch = Instant.now().minus(Duration.ofMinutes(10)).toEpochMilli();

        ConfigManager cfg = mock(ConfigManager.class);
        when(cfg.getConfiguration("tutortimer", "lastClaim")).thenReturn(null);
        when(cfg.getConfiguration("tutortimer", "lastKnownCooldown")).thenReturn(String.valueOf(epoch));
        setField(plugin, "configManager", cfg);

        plugin.loadLastClaimTime();

        assertTrue((boolean) getField(plugin, "knownOnCooldown"));
    }

    @Test
    public void loadLastClaimTime_expiredKnownCooldownIgnored() throws Exception
    {
        TutorTimerPlugin plugin = new TutorTimerPlugin();
        long epoch = Instant.now().minus(Duration.ofMinutes(31)).toEpochMilli();

        ConfigManager cfg = mock(ConfigManager.class);
        when(cfg.getConfiguration("tutortimer", "lastClaim")).thenReturn(null);
        when(cfg.getConfiguration("tutortimer", "lastKnownCooldown")).thenReturn(String.valueOf(epoch));
        setField(plugin, "configManager", cfg);

        plugin.loadLastClaimTime();

        assertFalse((boolean) getField(plugin, "knownOnCooldown"));
    }

    @Test
    public void loadLastClaimTime_clearsStaleClaimFromShutdown() throws Exception
    {
        TutorTimerPlugin plugin = new TutorTimerPlugin();
        long now = System.currentTimeMillis();
        long claim = now - Duration.ofMinutes(10).toMillis();
        long shutdown = now - Duration.ofMinutes(5).toMillis();

        ConfigManager cfg = mock(ConfigManager.class);
        when(cfg.getConfiguration("tutortimer", "lastClaim")).thenReturn(String.valueOf(claim));
        when(cfg.getConfiguration("tutortimer", "lastKnownCooldown")).thenReturn(null);
        when(cfg.getConfiguration("tutortimer", "lastShutdown")).thenReturn(String.valueOf(shutdown));
        setField(plugin, "configManager", cfg);

        plugin.loadLastClaimTime();

        Object val = getField(plugin, "lastClaimTime");
        assertFalse("stale claim should be cleared", ((java.util.Optional<?>) val).isPresent());
    }

    @Test
    public void loadLastClaimTime_doesNotClearClaimWhenShutdownOutsideWindow() throws Exception
    {
        TutorTimerPlugin plugin = new TutorTimerPlugin();
        long now = System.currentTimeMillis();
        long claim = now - Duration.ofMinutes(10).toMillis();
        // shutdown either before the claim or after expiry
        long shutdown = now - Duration.ofMinutes(40).toMillis();

        ConfigManager cfg = mock(ConfigManager.class);
        when(cfg.getConfiguration("tutortimer", "lastClaim")).thenReturn(String.valueOf(claim));
        when(cfg.getConfiguration("tutortimer", "lastKnownCooldown")).thenReturn(null);
        when(cfg.getConfiguration("tutortimer", "lastShutdown")).thenReturn(String.valueOf(shutdown));
        setField(plugin, "configManager", cfg);

        plugin.loadLastClaimTime();

        Object val = getField(plugin, "lastClaimTime");
        assertTrue("claim should survive when shutdown outside cooldown", ((java.util.Optional<?>) val).isPresent());
    }

    @Test
    public void loadLastClaimTime_keepsClaimWhenNoShutdownKey() throws Exception
    {
        TutorTimerPlugin plugin = new TutorTimerPlugin();
        long now = System.currentTimeMillis();
        long claim = now - Duration.ofMinutes(10).toMillis();

        ConfigManager cfg = mock(ConfigManager.class);
        when(cfg.getConfiguration("tutortimer", "lastClaim")).thenReturn(String.valueOf(claim));
        when(cfg.getConfiguration("tutortimer", "lastKnownCooldown")).thenReturn(null);
        when(cfg.getConfiguration("tutortimer", "lastShutdown")).thenReturn(null);
        setField(plugin, "configManager", cfg);

        plugin.loadLastClaimTime();

        Object val = getField(plugin, "lastClaimTime");
        assertTrue("claim should remain when shutdown key absent", ((java.util.Optional<?>) val).isPresent());
    }

    @Test
    public void loadLastClaimTime_handlesMalformedShutdown() throws Exception
    {
        TutorTimerPlugin plugin = new TutorTimerPlugin();
        long now = System.currentTimeMillis();
        long claim = now - Duration.ofMinutes(10).toMillis();

        ConfigManager cfg = mock(ConfigManager.class);
        when(cfg.getConfiguration("tutortimer", "lastClaim")).thenReturn(String.valueOf(claim));
        when(cfg.getConfiguration("tutortimer", "lastKnownCooldown")).thenReturn(null);
        when(cfg.getConfiguration("tutortimer", "lastShutdown")).thenReturn("not-a-number");
        setField(plugin, "configManager", cfg);

        plugin.loadLastClaimTime();

        Object val = getField(plugin, "lastClaimTime");
        assertTrue("claim should survive when shutdown value malformed", ((java.util.Optional<?>) val).isPresent());
        // log warning is emitted, but not asserted here
    }

